package cn.bidcheck.verification.engine;

import cn.bidcheck.domain.Domain.Document;
import cn.bidcheck.domain.Domain.Page;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static cn.bidcheck.verification.engine.VerificationTypes.*;

class PersonnelCredentialCounterevidenceTest {
    private static final String NUMBER="京1999999999990001";
    private static final String APPOINTMENT="投标文件\n项目名称：北方中心装修工程\n本项目拟派李明担任施工负责人。\n姓名：李明\n身份证号：110101198001010010";
    private static final String CERT="一级建造师注册证书\n姓名：李明\n身份证号：110101198001010010\n出生日期：1980-01-01\n注册编号："+NUMBER+"\n聘用企业：北方建设有限公司\n注册专业：建筑工程(有效期：2024-01-01至2027-12-31)";
    private static Rule rule(String predicate,Map<String,Object> extra){String quote="施工负责人须具有二级含以上注册建造师执业资格证书（房屋建筑工程专业），证书在投标截止日期有效。";Map<String,Object> p=linked("personnelCredentialKind","REGISTERED_BUILDER","category","注册建造师执业资格证书","requiredGrade","二级","gradeInclusive",true,"requiredProfession","房屋建筑工程");p.putAll(extra);return new Rule("r",quote,predicate,"施工负责人","证书","","","",p,quote,"",cn.bidcheck.compat.Java8Api.listOf());}
    private static RuleEvaluator evaluator(String... additional){List<Page> pages=new ArrayList<>(cn.bidcheck.compat.Java8Api.listOf(new Page(1,APPOINTMENT,"PAGE","TEXT",""), new Page(2,CERT,"PAGE","TEXT","")));for(String text:additional)pages.add(new Page(pages.size()+1,text,"PAGE","TEXT",""));EvidenceCorpus corpus=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(new Document("b","p","BID","投标文件",1,"h","",pages,cn.bidcheck.compat.Java8Api.listOf())));Fact role=new Fact("role","PERSON_ROLE","施工负责人","姓名","李明","李明","","","CURRENT_PROJECT",cn.bidcheck.compat.Java8Api.listOf(corpus.all.get(0).id()),cn.bidcheck.compat.Java8Api.mapOf());return new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(role),corpus,linked("referenceDate","2025-08-05","referenceDateSourceVerified",true,"referenceDateEvidence",cn.bidcheck.compat.Java8Api.mapOf("documentId", "t", "quote", "投标截止日期：2025年8月5日", "confirmation", "SOURCE_UNAMBIGUOUS", "confirmed", true)));}
    private static String query(String holder,String suffix){return "查询结果\n| 姓名 | 人员类型 | 注册编号 | 证书状态 |\n| --- | --- | --- | --- |\n| "+holder+" | 一级建造师 | "+NUMBER+" | "+suffix+" |";}
    @Test void independentlyCalculatedSingleRecordPassHasAClosure(){Decision d=evaluator().evaluate(rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf()));assertEquals("PASS",d.status(),d.toString());assertTrue(d.proof().containsKey("sourceReviewClosure"));}
    @Test void sameNumberDifferentHolderQueryCannotHideBehindSelectedPersonsName(){Decision d=evaluator(query("王明","有效")).evaluate(rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf()));assertEquals("UNDETERMINED",d.status(),d.toString());assertTrue(d.gaps().stream().anyMatch(g->g.code().equals("SAME_CREDENTIAL_HOLDER_CONFLICT")));}
    @Test void sameNumberMalformedCompetitorDoesNotDisappearWhenNoOwnerCanBeParsed(){Decision d=evaluator(CERT.replace("姓名：李明\n","")).evaluate(rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf()));assertEquals("UNDETERMINED",d.status(),d.toString());assertTrue(d.gaps().stream().anyMatch(g->g.code().equals("SAME_CREDENTIAL_COUNTEREVIDENCE_UNRESOLVED")));}
    @Test void unmappedNumberedQueryRowCannotBeCoveredByAnotherValidRow(){String query=query("李明","有效")+"\n| 未识别 | 一级建造师 | "+NUMBER+" |";Decision d=evaluator(query).evaluate(rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf()));assertEquals("UNDETERMINED",d.status(),d.toString());assertTrue(d.gaps().stream().anyMatch(g->g.code().equals("SAME_CREDENTIAL_COUNTEREVIDENCE_UNRESOLVED")));}
    @Test void revocationMustBelongToTheSelectedNumberedRow(){Decision d=evaluator(query("李明","已注销")).evaluate(rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf()));assertEquals("UNDETERMINED",d.status(),d.toString());assertTrue(d.gaps().stream().anyMatch(g->g.code().equals("SAME_CREDENTIAL_REVOCATION_FOUND")));Decision other=evaluator(query("李明","有效")+"\n| 王明 | 一级建造师 | 京9999999999999999 | 已注销 |").evaluate(rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf()));assertEquals("PASS",other.status(),other.toString());}
    @Test void historicalCertificateDoesNotBecomeCurrentCounterevidence(){Decision d=evaluator("历史项目\n"+CERT.replace("李明","王明")).evaluate(rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf()));assertEquals("PASS",d.status(),d.toString());}
    @Test void competingCurrentValidityVersionsRemainUnresolved(){Decision d=evaluator(CERT.replace("2027-12-31","2024-12-31")).evaluate(rule("VALIDITY",cn.bidcheck.compat.Java8Api.mapOf()));assertEquals("UNDETERMINED",d.status(),d.toString());assertTrue(d.gaps().stream().anyMatch(g->g.code().equals("CERTIFICATE_SELECTION_REQUIRED")));}
    @Test void sameHolderWithDifferentIdentifierCannotUseTheGoodVersion(){Decision d=evaluator(CERT.replace("110101198001010010","110101198001010029")).evaluate(rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf()));assertNotEquals("PASS",d.status());}
    @Test void unchangedNumbersInOtherCredentialFamiliesAreNotTheSelectedProof(){Decision d=evaluator("建筑施工企业项目负责人安全生产考核合格证书\n姓名：李明\n证件号码：110101198001010010\n编号：京建安B(2099)9990001\n有效期：2024年1月1日至2027年1月1日").evaluate(rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf()));assertEquals("PASS",d.status(),d.toString());}
    @Test void privateSelectionRejectsChangedSources(){RuleEvaluator evaluator=evaluator();Rule rule=rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf());cn.bidcheck.verification.engine.PersonnelCredentialProof.SelectedEvaluation result=PersonnelCredentialProof.evaluateSelected(rule,evaluator);assertNotNull(result.selection());Source removed=evaluator.corpus.all.remove(evaluator.corpus.all.size()-1);assertFalse(result.selection().authorizes(rule,evaluator,result.decision()));evaluator.corpus.all.add(removed);assertTrue(result.selection().authorizes(rule,evaluator,result.decision()));evaluator.corpus.byId.remove(removed.id());assertFalse(result.selection().authorizes(rule,evaluator,result.decision()));}
    @Test void sourceReviewReceiptAlsoExpiresWhenCurrentSourcesChange(){RuleEvaluator evaluator=evaluator();Rule rule=rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf());Decision decision=evaluator.evaluate(rule);assertEquals("PASS",decision.status());assertSame(decision,evaluator.closeSourceReview(rule,decision));evaluator.corpus.all.remove(evaluator.corpus.all.size()-1);assertNull(evaluator.closeSourceReview(rule,decision));}
    @Test void sourceClosureDoesNotOverrideRequiredWholeDocumentOcrCoverage(){RuleEvaluator evaluator=evaluator();cn.bidcheck.domain.Domain.Document d=evaluator.corpus.documents.get(0);List<Page> pages=new ArrayList<>(d.pages());pages.add(new Page(3,"","PAGE","OCR","[OCR_DEFERRED]"));EvidenceCorpus corpus=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(new Document(d.id(),d.projectId(),d.role(),d.name(),d.version(),d.sha256(),d.createdAt(),pages,d.warnings())));RuleEvaluator guarded=new RuleEvaluator(evaluator.facts,corpus,evaluator.context);Decision decision=guarded.evaluate(rule("CERTIFICATE",cn.bidcheck.compat.Java8Api.mapOf("requiresFullDocument", true)));assertEquals("UNDETERMINED",decision.status());assertTrue(decision.gaps().stream().anyMatch(g->g.code().equals("OCR_PLAN_COVERAGE_REQUIRED")));}
}
